window.Logistics=(()=>{'use strict';const E=x=>escapeHTML(x),L=LogisticsCore;let state,host,view='overview',selected='',busy=false,renderEpoch=0;const label={planned:'待发运',running:'运输中',arrived:'待签收',delivered:'已交付',cancelled:'已取消'};const field=(title,name,type='text',value='',extra='')=>`<label class="field">${title}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;const options=(list,key,labelFn)=>list.map(x=>`<option value="${E(x[key])}">${E(labelFn(x))}</option>`).join('');const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="empty">暂无记录。请先创建作业或载入教学样例。</td></tr>`}</tbody></table></div>`;
function taskRows(list,action=true){return list.map(t=>{const p=state.products.find(p=>p.id===t.product),v=state.vehicles.find(v=>v.id===t.vehicle);return `<tr><td><button class="text-btn" data-select="${t.id}">${t.id}</button></td><td>${E(p?.name)}<small>${t.qty} 箱</small></td><td>${E(t.destination)}</td><td>${E(v?.plate)}</td><td><span class="badge ${t.status==='delivered'?'':'gray'}">${label[t.status]}</span></td><td>${t.progress.toFixed(1)} / ${t.distance} km</td>${action?`<td>${t.status==='planned'?`<button class="btn compact" data-action="dispatch" data-id="${t.id}">发运</button> <button class="btn compact" data-action="cancel" data-id="${t.id}">取消</button>`:t.status==='running'?`<button class="btn compact" data-select="${t.id}">监控</button>`:t.status==='arrived'?`<button class="btn compact" data-deliver="${t.id}">签收</button>`:'—'}</td>`:''}</tr>`}).join('')}
async function commit(action,d){if(busy)return;busy=true;host.inert=true;try{const next=L.apply(state,action,d);await api('logistics','POST',next);state=next;ui();toast('作业已保存')}finally{busy=false;host.inert=false}}
function map(t){const width=760,height=300,progress=t?t.progress/t.distance:0;return `<div class="route-map"><div class="map-label">教学路线示意 / 非真实地理底图</div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="运输路径与模拟车辆位置"><defs><pattern id="grid" width="38" height="30" patternUnits="userSpaceOnUse"><path d="M38 0H0V30" fill="none" stroke="#e2e8ed" stroke-width="1"/></pattern></defs><rect width="760" height="300" fill="url(#grid)"/><path d="M0 80H760M0 220H760M180 0V300M550 0V300" stroke="#fff" stroke-width="18"/><path d="M65 180C220 180 230 100 390 100S550 180 685 180" stroke="#b8cbdd" stroke-width="20" fill="none"/><path d="M70 150H690" stroke="#3668a5" stroke-width="4" stroke-dasharray="10 6"/><circle cx="70" cy="150" r="9" fill="#255f9c"/><circle cx="690" cy="150" r="9" fill="#188578"/><text x="35" y="187">发货仓</text><text x="636" y="187">配送终点</text>${t?`<path d="M70 150H${70+620*progress}" stroke="#188578" stroke-width="5"/><circle cx="${70+620*progress}" cy="${150-Math.max(-8,Math.min(8,t.y))*10}" r="12" fill="#173f70" stroke="white" stroke-width="4"/><text x="${Math.max(30,Math.min(640,45+620*progress))}" y="${123-Math.max(-8,Math.min(8,t.y))*10}">${E(t.id)}</text>`:''}</svg><div class="map-footer"><span>规划长度 ${t?t.distance:'—'} km</span><span>横向偏移 ${t?t.y:0} km · 容差 ±2 km</span></div></div>`}
function ui(){const titles={overview:'物流作业工作台',warehouse:'仓储与库存',transport:'运输调度',coldchain:'冷链监控',alarms:'告警处置',reports:'实训证据与报告',calendar:'教学日历',cases:'综合实践案例'};host.innerHTML=`<div class="page-head"><div><div class="eyebrow">LOGISTICS OPERATIONS / 教学工作空间</div><h1>${titles[view]}</h1><p class="muted">仓储、调度、冷链监控与教学成果的完整业务链路</p></div><div class="toolbar"><button class="btn" id="exportLogistics">导出作业数据</button>${!state.products.length?'<button class="btn primary" id="loadDemo">载入教学样例</button>':''}</div></div><div id="workBody"></div>`;const el=host.querySelector('#workBody');
if(view==='overview'){const pending=state.tasks.filter(t=>['planned','running','arrived'].includes(t.status));el.innerHTML=`<div class="metric-strip">${[['在库数量',state.products.reduce((a,p)=>a+p.stock,0),'箱'],['待办运输',pending.length,'单'],['未确认告警',state.alarms.filter(a=>!a.ack).length,'条'],['完成交付',state.tasks.filter(t=>t.status==='delivered').length,'单']].map(([t,v,u])=>`<div><span>${t}</span><strong>${v}<small>${u}</small></strong></div>`).join('')}</div><div class="workflow"><span>01 入库登记</span><i>→</i><span>02 库存预留</span><i>→</i><span>03 出库发运</span><i>→</i><span>04 遥测与告警</span><i>→</i><span>05 交付与复盘</span></div><div class="workspace-split"><section class="card"><div class="section-title"><h2>当前作业</h2><button class="btn primary" onclick="navigate('transport')">新建运输任务</button></div>${table(['运单','货品','目的地','车辆','状态','进度','操作'],taskRows(pending))}${map(pending.find(t=>t.status==='running')||pending[0])}</section><section class="card"><h2>值班记录</h2><p class="muted">模拟时钟 ${state.clock} min · 所有记录仅保存在当前浏览器。</p>${state.ledger.slice(0,7).map(l=>`<div class="log-item"><span>${l.type}</span><small>${E(l.detail)}<br>${l.minute} min</small></div>`).join('')||'<p class="muted">载入教学样例或登记第一笔入库，开始完整实训。</p>'}<div class="divider"></div><h3>课堂起步</h3><p class="muted">先登记入库与车辆，再建立运输计划。发运后注入模拟采样，观察异常，最终完成签收并导出证据。</p><button class="btn" onclick="navigate('cases')">查看案例任务</button></section></div>`}
if(view==='warehouse'){el.innerHTML=`<div class="workspace-split"><section class="card"><h2>库存台账</h2>${table(['SKU / 货品','库位','在库','已预留','可用','环境要求'],state.products.map(p=>`<tr><td><b>${E(p.sku)}</b><small>${E(p.name)}</small></td><td>${E(p.zone)}</td><td>${p.stock}</td><td>${p.stock-L.available(state,p)}</td><td><b>${L.available(state,p)}</b></td><td>${p.min}~${p.max}°C<small>湿度 ≤ ${p.humidity}%</small></td></tr>`).join(''))}<h2 style="margin-top:28px">库存流水</h2>${table(['编号','类型','货品','数量变化','作业详情'],state.ledger.filter(l=>l.delta).map(l=>`<tr><td>${l.id}</td><td>${l.type}</td><td>${E(state.products.find(p=>p.id===l.product)?.sku)}</td><td>${l.delta>0?'+':''}${l.delta}</td><td>${E(l.detail)}</td></tr>`).join(''))}</section><section class="card"><h2>入库登记</h2><form data-form="receive">${field('SKU 编码','sku','text','','required maxlength="40"')}${field('货品名称（新 SKU 必填）','name','text','','maxlength="100"')}${field('库位','zone','text','冷藏 A-01','required maxlength="40"')}${field('入库数量 / 箱','qty','number',10,'required min="1" max="100000" step="1"')}<div class="grid two">${field('最低温度 °C','min','number',2,'required min="-50" max="50" step="0.1"')}${field('最高温度 °C','max','number',8,'required min="-50" max="80" step="0.1"')}</div>${field('湿度上限 %','humidity','number',85,'required min="1" max="100"')}<p class="muted">已有 SKU 将增加原台账库存，名称、库位和阈值保持原登记值。</p><button class="btn primary">确认入库</button></form></section></div>`}
if(view==='transport'){el.innerHTML=`<section class="card"><div class="section-title"><h2>运输任务</h2><span class="muted">计划预留库存，发运扣减库存，交付保存签收证据</span></div>${table(['运单','货品','目的地','车辆','状态','进度','操作'],taskRows(state.tasks))}</section><div class="grid two" style="margin-top:20px"><section class="card"><h2>创建运输计划</h2><form data-form="plan"><div class="grid two"><label class="field">出库货品<select name="product" required>${options(state.products,'id',p=>p.sku+' · 可用 '+L.available(state,p)+' 箱')}</select></label><label class="field">车辆<select name="vehicle" required>${options(state.vehicles,'id',v=>v.plate+' · '+v.capacity+' 箱')}</select></label>${field('装载数量 / 箱','qty','number',20,'required min="1" step="1"')}${field('目的地','destination','text','教学配送中心','required maxlength="80"')}${field('规划路程 / km','distance','number',30,'required min="1" max="2000"')}${field('时效要求 / min','duration','number',60,'required min="1" max="10000"')}</div><button class="btn primary">校验并创建计划</button></form></section><section class="card"><h2>车辆档案</h2>${table(['车辆编号','驾驶员','容量','冷藏'],state.vehicles.map(v=>`<tr><td>${E(v.plate)}</td><td>${E(v.driver)}</td><td>${v.capacity} 箱</td><td>${v.cold?'支持':'不支持'}</td></tr>`).join(''))}<form data-form="vehicle" class="grid two" style="margin-top:18px">${field('车辆编号','plate','text','','required maxlength="30"')}${field('驾驶员 / 教学代号','driver','text','','required maxlength="40"')}${field('载货容量 / 箱','capacity','number',60,'required min="1" step="1"')}<label class="field">冷藏能力<select name="cold"><option value="true">支持冷藏</option><option value="">普通车辆</option></select></label><button class="btn">登记车辆</button></form></section></div>`}
if(view==='coldchain'){const t=state.tasks.find(t=>t.id===selected)||state.tasks.find(t=>t.status==='running')||state.tasks[0];selected=t?.id||'';const p=state.products.find(p=>p.id===t?.product);el.innerHTML=`<div class="toolbar"><label>监控运单 <select id="monitorTask">${state.tasks.map(v=>`<option ${v.id===selected?'selected':''} value="${v.id}">${v.id} · ${E(v.destination)} · ${label[v.status]}</option>`).join('')}</select></label><span class="badge gray">本地仿真模式 · 设备未连接</span></div><div class="workspace-split"><section class="card"><div class="section-title"><h2>路线与位置</h2><span>${t?label[t.status]:'暂无运输任务'}</span></div>${map(t)}<div class="metric-strip">${[['当前温度',t?.temp??'—','°C'],['相对湿度',t?.humidity??'—','%'],['模拟耗时',t?.elapsed??0,'min']].map(([a,b,d])=>`<div><span>${a}</span><strong>${b}<small>${d}</small></strong></div>`).join('')}</div><h2>采样记录</h2>${table(['模拟分钟','温度','湿度','设备状态','行进 / 偏移'],state.telemetry.filter(s=>s.task===selected).slice(-12).reverse().map(s=>`<tr><td>${s.minute}</td><td>${s.temp}°C</td><td>${s.humidity}%</td><td>${s.online?'在线（模拟）':'离线（模拟）'}</td><td>${s.x} / ${s.y} km</td></tr>`).join(''))}</section><section class="card"><h2>模拟采样控制</h2><p class="muted">每次提交推进全局模拟时钟，同时记录阈值、离线、偏航及运输超时告警。</p><form data-form="sample"><input type="hidden" name="id" value="${E(t?.id||'')}">${field('推进时间 / min','minutes','number',15,'required min="1" max="120"')}${field('行进距离 / km','distance','number',10,`required min="0" max="${t?.distance||2000}" step="0.1"`)}${field('路线横向偏离 / km','offset','number',0,'required min="-100" max="100" step="0.1"')}<div class="grid two">${field('温度 °C','temp','number',t?.temp??5,'required min="-70" max="100" step="0.1"')}${field('湿度 %','humidity','number',t?.humidity??50,'required min="0" max="100"')}</div><label class="field">采样连接<select name="online"><option value="true">在线（模拟）</option><option value="">离线（模拟）</option></select></label><p class="muted">${p?`当前阈值 ${p.min}~${p.max}°C · 湿度 ≤${p.humidity}%`:'请先创建并发运运输任务'}</p><button class="btn primary" ${t?.status!=='running'?'disabled':''}>提交模拟采样</button></form>${t?.status==='arrived'?`<button class="btn primary" style="margin-top:16px" data-deliver="${t.id}">办理签收</button>`:''}</section></div>`;el.querySelector('#monitorTask').onchange=e=>{selected=e.target.value;ui()}}
if(view==='alarms'){el.innerHTML=`<section class="card"><div class="section-title"><h2>异常事件队列</h2><span class="muted">确认表示已阅读；后续正常采样将标记测量恢复</span></div>${table(['告警','运单','详情','发生分钟','状态','处置'],state.alarms.map(a=>`<tr><td><span class="badge ${a.resolved?'gray':'red'}">${a.type}</span></td><td>${a.task}</td><td>${E(a.detail)}</td><td>${a.minute}</td><td>${a.resolved?'已恢复':'异常记录'} / ${a.ack?'已确认':'待确认'}</td><td>${a.ack?E(a.note):`<button class="btn" data-ack="${a.id}">确认与备注</button>`}</td></tr>`).join(''))}<p class="muted">历史告警保留用于复盘。运输超时记录不会因签收自动删除，确认不会改变库存或运输状态。</p></section>`}
if(view==='reports'){el.innerHTML=`<div class="workspace-split"><section class="card"><h2>实训报告记录</h2>${table(['报告','学员','关联运单','保存时间','下载'],state.reports.map((r,i)=>`<tr><td>${E(r.title)}<small>${E(r.observations.slice(0,100))}</small></td><td>${E(r.learner)}</td><td>${E(r.task)}</td><td>${new Date(r.at).toLocaleString('zh-CN')}</td><td><button class="btn" data-report="${i}">证据 JSON</button></td></tr>`).join(''))}<h2 style="margin-top:24px">审计流水</h2>${table(['编号','动作','模拟分钟','详情'],state.ledger.slice(0,60).map(l=>`<tr><td>${l.id}</td><td>${l.type}</td><td>${l.minute}</td><td>${E(l.detail)}</td></tr>`).join(''))}</section><section class="card"><h2>保存实训报告</h2><form data-form="report">${field('报告标题','title','text','冷链运输全流程实训','required maxlength="100"')}${field('学员姓名 / 教学代号','learner','text','','required maxlength="40"')}<label class="field">关联运单<select name="task" required>${options(state.tasks,'id',t=>t.id+' · '+label[t.status])}</select></label><label class="field">观察与结论<textarea name="observations" required maxlength="5000" rows="8" placeholder="说明温度异常、处置措施、库存变化与业务结果"></textarea></label><p class="muted">保存当前物流台账、运单、采样与告警快照，形成可追溯教学证据。报告为练习记录。</p><button class="btn primary">保存报告与证据</button></form></section></div>`;el.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>downloadJSON('training-evidence-'+state.reports[+b.dataset.report].id+'.json',state.reports[+b.dataset.report]))}
if(view==='calendar'){el.innerHTML=`<div class="workspace-split"><section class="card"><h2>教学计划</h2>${table(['日期','课程 / 实验','班级'],[...state.calendar].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<tr><td>${e.date}</td><td>${E(e.title)}</td><td>${E(e.className)}</td></tr>`).join(''))}</section><section class="card"><h2>添加教学安排</h2><form data-form="calendar">${field('日期','date','date',new Date().toISOString().slice(0,10),'required')}${field('任务名称','title','text','','required maxlength="100"')}${field('班级 / 小组','className','text','','required maxlength="80"')}<button class="btn primary">保存安排</button></form><p class="muted">仅保存本地教学日历，不发送邀请或外部提醒。</p></section></div>`}
if(view==='cases'){const cases=[['智慧校园','校园设备巡检与环境告警','twin','创建教室温度、照明、门禁组件。设置温度阈值并注入越界读数，测试联动逻辑。','提交设备拓扑、异常日志和节能建议。门禁与身份事件均为教学仿真。'],['智慧仓储','入库、库存与出库闭环','warehouse','录入两个 SKU 和不同温湿度阈值；为两个运输计划分别预留库存，测试超量拦截，再发运。','检查在库、预留、可用数量满足：可用 = 在库 − 待发运预留；核对每笔库存流水。'],['智慧运输','冷链配送与异常处置','transport','创建 30 km / 60 min 冷链任务。发运后分别注入 12°C 高温、4 km 偏航、离线和超时，再恢复正常。','确认告警并记录措施，完成到达和签收，导出完整实训证据。'],['口罩检测','通用视觉基线与专用数据准备','annotation','上传合法授权的练习图片，体验通用目标检测；人工添加口罩/未佩戴标签、矩形框与关键点。','内置 COCO-SSD 不包含专用口罩类。导出标注数据用于后续专用训练，不能把通用模型结果当口罩识别成果。'],['智慧温室','环境采集、阈值与执行器','twin','建立温湿度、照明、风机等仿真组件，设计高温告警和通风动作；对正常、越界和设备失联做记录。','提交阈值依据、场景配置和观察报告。执行器为本地交互，不连接真实温室。']];el.innerHTML=`<section class="card"><h2>五类综合实践任务</h2>${cases.map(([name,title,page,steps,out],i)=>`<div class="case-row"><span class="case-number">0${i+1}</span><div><h3>${name} · ${title}</h3><p>${steps}</p><p class="muted">验收产物：${out}</p></div><button class="btn" onclick="navigate('${page}')">进入实训</button></div>`).join('')}</section><section class="card" style="margin-top:20px"><h2>交付边界</h2><p>本平台为浏览器持久化教学 MVP。硬件接入、真实车辆和无人机控制、统一账号权限、跨浏览器同步、专用口罩模型、工业专用类别与可靠领域大模型能力仍需后续建设；当前已提供 1500 道主问题的默认题库，新增原创 AI 草稿仍待教师学科审核；知识面板已提供一次小样本 CPU LoRA 完成记录。</p><p class="muted">默认题库 <span data-default-bank-count>读取中</span> 道（新增原创 AI 草稿待教师审核），支持导入扩充，通用检测模型覆盖 COCO 80 类。所有教学样例均为虚构练习数据，未使用真实学校标识、客户名单或认证材料。</p></section>`}
const bankCount=host.querySelector('[data-default-bank-count]');if(bankCount)fetch('/data/questions.json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json()}).then(rows=>{if(bankCount.isConnected)bankCount.textContent=new Set(rows.map(q=>q.id)).size}).catch(()=>{if(bankCount.isConnected)bankCount.textContent='暂不可读';});
host.querySelector('#exportLogistics').onclick=()=>downloadJSON('logistics-workspace.json',state);const demo=host.querySelector('#loadDemo');if(demo)demo.onclick=async()=>{if(busy)return;busy=true;try{const next=L.demo(state);await api('logistics','POST',next);state=next;ui();toast('已载入虚构教学样例')}finally{busy=false}};
host.querySelectorAll('form[data-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();commit(f.dataset.form,Object.fromEntries(new FormData(f))).catch(e=>toast(e.message))});host.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>commit(b.dataset.action,{id:b.dataset.id}).catch(e=>toast(e.message)));host.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;navigate('coldchain')});host.querySelectorAll('[data-deliver]').forEach(b=>b.onclick=()=>{const receiver=prompt('填写签收人或教学代号');if(receiver)commit('deliver',{id:b.dataset.deliver,receiver}).catch(e=>toast(e.message))});host.querySelectorAll('[data-ack]').forEach(b=>b.onclick=()=>{const note=prompt('填写处置备注');if(note)commit('ack',{id:b.dataset.ack,note}).catch(e=>toast(e.message))});}
return{async render(c,page){const epoch=++renderEpoch,data=await api('logistics');if(epoch!==renderEpoch)return;state=data||L.initial();host=c;view=page;ui()},async stop(){renderEpoch++;while(busy)await new Promise(r=>setTimeout(r,10))}}})();
